<script setup>import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import PageHero from '../components/PageHero.vue';import{images}from'../data/imageAssets';import{getPersonById}from'../api/people';import{toDisplayImageUrl}from'../utils/imageUrl.js';const route=useRoute(),person=ref(null),failed=ref(false);onMounted(async()=>{try{person.value=await getPersonById(route.params.id)}catch{failed.value=true}})</script>
<template><PageHero :title="person?.name||'人物资料'" description="历史人物详情" :image="toDisplayImageUrl(person?.image)||images.personPlaceholder"/><section class="section"><div class="shell" v-if="person"><h2>{{person.name}}</h2><p>{{person.role}}</p><p>{{person.relation}}</p><p>{{person.content}}</p><p v-if="person.imageCaption" class="source-note">图片说明：{{ person.imageCaption }}</p><a :href="person.sourceUrl" target="_blank" rel="noreferrer">资料来源</a></div><div v-else class="empty-state">{{failed?'人物资料暂时无法加载，请稍后重试。':'正在加载…'}}<RouterLink class="button" to="/people">返回人物列表</RouterLink></div></section></template>
